#!/usr/bin/env python3

import json
import sys
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


class RequestFailed(Exception):
    def __init__(self, status_code, body):
        self.status_code = status_code
        self.body = body
        super().__init__(body)


def load_models(config_path):
    with open(config_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    models = []

    def add_model(item):
        if isinstance(item, str):
            models.append(item)
        elif isinstance(item, dict):
            for key in ("model", "name", "id", "model_name"):
                value = item.get(key)
                if isinstance(value, str):
                    models.append(value)
                    return

            litellm_params = item.get("litellm_params")
            if isinstance(litellm_params, dict):
                value = litellm_params.get("model")
                if isinstance(value, str):
                    models.append(value)

    if isinstance(data, list):
        for item in data:
            add_model(item)
    elif isinstance(data, dict):
        if isinstance(data.get("models"), list):
            for item in data["models"]:
                add_model(item)
        elif isinstance(data.get("model_list"), list):
            for item in data["model_list"]:
                add_model(item)
        else:
            add_model(data)

    if not models:
        raise ValueError("No models found in config file")

    return models


def make_payload(model, include_temperature):
    payload = {
        "model": model,
        "messages": [
            {
                "role": "user",
                "content": PROMPT,
            }
        ],
        "max_tokens": 20,
    }

    if include_temperature:
        payload["temperature"] = 0

    return payload


def post_chat_completion(model, include_temperature):
    payload = make_payload(model, include_temperature)
    data = json.dumps(payload).encode("utf-8")

    request = urllib.request.Request(
        API_URL,
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
            return response.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        raise RequestFailed(e.code, body)


def extract_response_text(body):
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return body

    choices = data.get("choices")
    if isinstance(choices, list) and choices:
        choice = choices[0]

        message = choice.get("message")
        if isinstance(message, dict):
            content = message.get("content")
            if content is not None:
                return str(content)

        text = choice.get("text")
        if text is not None:
            return str(text)

    return body


def extract_error_text(body):
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return body

    error = data.get("error")
    if isinstance(error, dict):
        return str(error.get("message", body))
    if isinstance(error, str):
        return error

    return body


def is_temperature_unsupported(error_text):
    text = error_text.lower()

    if "temperature" not in text:
        return False

    indicators = [
        "unsupported",
        "not support",
        "not supported",
        "does not support",
        "unrecognized",
        "unknown parameter",
        "invalid parameter",
        "not allowed",
        "extra inputs are not permitted",
    ]

    if any(indicator in text for indicator in indicators):
        return True

    if "only" in text and "support" in text:
        return True

    return False


def preview(text):
    text = "" if text is None else str(text)
    text = text[:50]
    text = text.replace("\r", "\\r").replace("\n", "\\n").replace("\t", "\\t")
    return text


def test_model(model):
    start = time.time()

    for include_temperature in (True, False):
        try:
            body = post_chat_completion(model, include_temperature)
            latency = time.time() - start
            response_text = extract_response_text(body)

            if response_text.strip() == "OK":
                status = "PASS"
            else:
                status = "FAIL"

            return {
                "model": model,
                "status": status,
                "latency": latency,
                "response": preview(response_text),
            }

        except RequestFailed as e:
            error_text = extract_error_text(e.body)

            if include_temperature and is_temperature_unsupported(error_text):
                continue

            latency = time.time() - start
            return {
                "model": model,
                "status": "FAIL",
                "latency": latency,
                "response": preview(error_text),
            }

        except Exception as e:
            latency = time.time() - start
            return {
                "model": model,
                "status": "FAIL",
                "latency": latency,
                "response": preview(str(e)),
            }

    latency = time.time() - start
    return {
        "model": model,
        "status": "FAIL",
        "latency": latency,
        "response": "Unknown failure",
    }


def print_table(results):
    model_width = max(len("Model"), max(len(r["model"]) for r in results))
    status_width = max(len("Status"), max(len(r["status"]) for r in results))
    latency_width = len("Latency")

    header = (
        f"{'Model':<{model_width}}  "
        f"{'Status':<{status_width}}  "
        f"{'Latency':>{latency_width}}  "
        f"Response"
    )

    separator = (
        f"{'-' * model_width}  "
        f"{'-' * status_width}  "
        f"{'-' * latency_width}  "
        f"{'-' * 50}"
    )

    print(header)
    print(separator)

    for r in results:
        latency = f"{r['latency']:.2f}s"
        print(
            f"{r['model']:<{model_width}}  "
            f"{r['status']:<{status_width}}  "
            f"{latency:>{latency_width}}  "
            f"{r['response']}"
        )


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} models.json", file=sys.stderr)
        sys.exit(1)

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Failed to load models: {e}", file=sys.stderr)
        sys.exit(1)

    results = []

    for model in models:
        results.append(test_model(model))

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["status"] == "PASS")
    failed = total - working

    print()
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
